+(()=>{
+const canvas=document.getElementById('view'),ctx=canvas.getContext('2d',{alpha:false}),$=s=>document.querySelector(s);
+let W=0,H=0,dpr=1;function resize(){dpr=Math.min(devicePixelRatio||1,1.5);W=innerWidth;H=innerHeight;canvas.width=W*dpr;canvas.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0)}addEventListener('resize',resize);resize();
