+function notify(text){const e=$('#toast');e.textContent=text;e.classList.add('show');toastTimer=2.2}
+function coords(wx,wy,wz){let dx=wx-player.x,dz=wz-player.z,sy=Math.sin(player.yaw),cy=Math.cos(player.yaw),sp=Math.sin(player.pitch),cp=Math.cos(player.pitch),forward=dx*sy+dz*cy;return{x:dx*cy-dz*sy,y:(wy-(player.y+1.55))*cp-forward*sp,z:forward*cp+(wy-(player.y+1.55))*sp}}
