+function proj(p){return{x:W/2+p.x*focal()/p.z,y:H*.51-p.y*focal()/p.z}}
+function cubeFaces(b){let x=b.x,y=b.y,z=b.z,verts=[[x,y,z],[x+1,y,z],[x+1,y+1,z],[x,y+1,z],[x,y,z+1],[x+1,y,z+1],[x+1,y+1,z+1],[x,y+1,z+1]],faces=[[0,1,2,3,[0,-1,0],'top'],[4,7,6,5,[0,1,0],'bottom'],[0,4,5,1,[0,0,-1],'front'],[1,5,6,2,[1,0,0],'right'],[4,0,3,7,[-1,0,0],'left'],[3,2,6,7,[0,0,1],'back']];let center=[x+.5,y+.5,z+.5],toCam=[player.x-center[0],player.y+1.55-center[1],player.z-center[2]];let tone={top:1.13,bottom:.58,front:.91,right:.78,left:1.04,back:.84};let out=[];for(let f of faces){if(f[4][0]*toCam[0]+f[4][1]*toCam[1]+f[4][2]*toCam[2]<=0)continue;let ps=f.slice(0,4).map(i=>coords(...verts[i]));if(ps.some(p=>p.z<.15))continue;out.push({ps,depth:ps.reduce((a,p)=>a+p.z,0)/4,color:b.t,shade:tone[f[5]]})}return out}
