function tint(hex,k){let n=parseInt(hex.slice(1),16),r=Math.min(255,((n>>16)&255)*k),g=Math.min(255,((n>>8)&255)*k),b=Math.min(255,(n&255)*k);return`rgb(${r|0},${g|0},${b|0})`}
function polyFace(points,color,alpha=1){let p=points.map(v=>coords(v[0],v[1],v[2]));if(p.some(v=>v.z<.15))return null;return{ps:p,depth:p.reduce((a,v)=>a+v.z,0)/p.length,color,alpha}}
function drawFace(f){let pts=f.ps.map(proj);ctx.globalAlpha=f.alpha||1;ctx.beginPath();ctx.moveTo(pts[0].x,pts[0].y);for(let i=1;i<pts.length;i++)ctx.lineTo(pts[i].x,pts[i].y);ctx.closePath();ctx.fillStyle=f.fill||tint(colors[f.color]||f.color,f.shade||1);ctx.fill();if(f.outline){ctx.strokeStyle=f.outline;ctx.lineWidth=1;ctx.stroke()}ctx.globalAlpha=1}
function dragonPieces(){if(!dragon.alive)return[];let bob=Math.sin(time*1.6)*.24,flap=Math.sin(time*5.2)*.72,x=dragon.x,y=dragon.y+bob,z=dragon.z,out=[];const box=(ox,oy,oz,s,t)=>{let b={x:x+ox-s/2,y:y+oy-s/2,z:z+oz-s/2,s,t};out.push(...cubeFaces(b))};box(0,0,0,.98,'obsidian');box(0,.15,-.82,.7,'ice');box(0,.22,-1.34,.5,'snow');box(0,-.02,1.04,.42,'obsidian');box(0,-.08,1.55,.29,'ice');box(-.43,-.38,-.1,.22,'ice');box(.43,-.38,-.1,.22,'ice');box(-.2,.36,-1.55,.13,'fire');box(.2,.36,-1.55,.13,'fire');
for(let side of [-1,1]){let wing=[[x+side*.3,y+.23,z-.12],[x+side*(1.15+flap*.22),y+1.55+flap*.48,z+.12],[x+side*2.35,y+.65+flap*.6,z+.85],[x+side*.88,y-.02,z+1.12]];let a=polyFace([wing[0],wing[1],wing[2]],'#427a90',.94),b=polyFace([wing[0],wing[2],wing[3]],'#315d78',.98);if(a)out.push(a);if(b)out.push(b);let rib=polyFace([wing[0],wing[1],wing[3]],'#9bd7d4',.32);if(rib)out.push(rib)}return out}
function render(){let sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,'#7096a2');sky.addColorStop(.52,'#b8c6ba');sky.addColorStop(1,'#e1d7b6');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);
// distant snowy peaks on the horizon
ctx.fillStyle='#748b8d';ctx.beginPath();ctx.moveTo(0,H*.5);for(let x=0;x<=W+40;x+=40){let yy=H*(.49+Math.sin(x*.009)*.045+Math.sin(x*.025)*.018);ctx.lineTo(x,yy)}ctx.lineTo(W,H);ctx.lineTo(0,H);ctx.closePath();ctx.fill();ctx.fillStyle='#c3d2c9';ctx.globalAlpha=.72;ctx.beginPath();ctx.moveTo(0,H*.52);for(let x=0;x<=W+55;x+=55)ctx.lineTo(x,H*(.5+Math.sin(x*.012+1)*.025));ctx.lineTo(W,H);ctx.lineTo(0,H);ctx.closePath();ctx.fill();ctx.globalAlpha=1;
let faces=[];for(const b of blocks.values()){let dx=b.x+.5-player.x,dz=b.z+.5-player.z;if(dx*dx+dz*dz>23*23)continue;faces.push(...cubeFaces(b))}faces.push(...dragonPieces());faces.sort((a,b)=>b.depth-a.depth);for(const f of faces)drawFace(f);
// atmospheric sparkles and dragon fire bolts
for(const f of fireballs){let p=coords(f.x,f.y,f.z);if(p.z>.2){let q=proj(p),r=Math.max(2,focal()*.14/p.z);let g=ctx.createRadialGradient(q.x,q.y,1,q.x,q.y,r);g.addColorStop(0,'#fff3b1');g.addColorStop(.35,'#ffb05b');g.addColorStop(1,'#ed4e38');ctx.fillStyle=g;ctx.beginPath();ctx.arc(q.x,q.y,r,0,Math.PI*2);ctx.fill()}}
if(damageFlash>0){ctx.fillStyle=`rgba(220,65,58,${damageFlash*.16})`;ctx.fillRect(0,0,W,H)}
}

